type PlaceOrderError =
  | { type: "not_found"; sku: string }
  | { type: "out_of_stock"; sku: string; available: number }
  | { type: "invalid_quantity"; quantity: number };

function suggestion(e: PlaceOrderError): string {
  switch (e.type) {
    case "not_found":
      return `We don't sell ${e.sku}. Try searching for it.`;
    case "out_of_stock":
      return `Only ${e.available} of ${e.sku} left. Order ${e.available} instead?`;
    case "invalid_quantity":
      return `${e.quantity} isn't a quantity. Enter 1 or more.`;
    default: {
      const unhandled: never = e;
      return unhandled;
    }
  }
}

const problems: PlaceOrderError[] = [
  { type: "not_found", sku: "LAMP-09" },
  { type: "out_of_stock", sku: "MUG-01", available: 2 },
  { type: "invalid_quantity", quantity: 0 },
];

for (const problem of problems) {
  console.log(`${problem.type}: ${suggestion(problem)}`);
}

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

function ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

function err<E>(error: E): Result<never, E> {
  return { ok: false, error };
}

type PlaceOrderError =
  | { type: "not_found"; sku: string }
  | { type: "out_of_stock"; sku: string; available: number }
  | { type: "invalid_quantity"; quantity: number };

type Order = { sku: string; quantity: number; totalCents: number };

const CATALOG = new Map([
  ["MUG-01", { priceCents: 1299, available: 2 }],
  ["TEA-02", { priceCents: 450, available: 10 }],
]);

function placeOrder(sku: string, quantity: number): Result<Order, PlaceOrderError> {
  if (!Number.isInteger(quantity) || quantity < 1) {
    return err({ type: "invalid_quantity", quantity });
  }
  const item = CATALOG.get(sku);
  if (item === undefined) {
    return err({ type: "not_found", sku });
  }
  if (quantity > item.available) {
    return err({ type: "out_of_stock", sku, available: item.available });
  }
  return ok({ sku, quantity, totalCents: quantity * item.priceCents });
}

function checkout(sku: string, quantity: number): string {
  const result = placeOrder(sku, quantity);
  if (result.ok) {
    return `ordered ${quantity} x ${sku} for $${(result.value.totalCents / 100).toFixed(2)}`;
  }
  const error = result.error;
  switch (error.type) {
    case "not_found":
      return `sorry, we don't sell ${error.sku}`;
    case "out_of_stock":
      return `sorry, only ${error.available} of ${error.sku} left`;
    case "invalid_quantity":
      return `${error.quantity} isn't a quantity you can order`;
  }
}

console.log(checkout("MUG-01", 2));
console.log(checkout("MUG-01", 5));
console.log(checkout("LAMP-09", 1));
console.log(checkout("TEA-02", 0));

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

function ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

function err<E>(error: E): Result<never, E> {
  return { ok: false, error };
}

function andThen<T, U, E>(r: Result<T, E>, fn: (value: T) => Result<U, E>): Result<U, E> {
  return r.ok ? fn(r.value) : r;
}

type CheckoutError =
  | { type: "bad_quantity"; text: string }
  | { type: "out_of_stock"; available: number };

const AVAILABLE = 5;

function parseQuantity(text: string): Result<number, CheckoutError> {
  const n = Number(text);
  return Number.isInteger(n) && n > 0 ? ok(n) : err({ type: "bad_quantity", text });
}

function reserve(quantity: number): Result<string, CheckoutError> {
  if (quantity > AVAILABLE) {
    return err({ type: "out_of_stock", available: AVAILABLE });
  }
  return ok(`reserved ${quantity}, ${AVAILABLE - quantity} left`);
}

for (const text of ["2", "two", "9"]) {
  const result = andThen(parseQuantity(text), reserve);
  //    ^? const result: Result<string, CheckoutError>
  if (result.ok) {
    console.log(`${text}: ${result.value}`);
  } else {
    console.log(`${text}: failed with ${result.error.type}`);
  }
}

