export type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

function ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

function err<E>(error: E): Result<never, E> {
  return { ok: false, error };
}

export type BookingError =
  | { type: "sold_out" }
  | { type: "too_many"; max: number }
  | { type: "vip_only" };

export function book(available: number, requested: number, vip: boolean): Result<number, BookingError> {
  if (available === 0) {
    return err({ type: "sold_out" });
  }
  const max = Math.min(4, available);
  if (requested > max) {
    return err({ type: "too_many", max });
  }
  if (available <= 10 && !vip) {
    return err({ type: "vip_only" });
  }
  return ok(available - requested);
}

export function describeError(e: BookingError): string {
  switch (e.type) {
    case "sold_out":
      return "sold out";
    case "too_many":
      return `you can book at most ${e.max} seats`;
    case "vip_only":
      return "the last 10 seats are for VIP members";
    default: {
      const unhandled: never = e;
      return unhandled;
    }
  }
}

const bookings: [available: number, requested: number, vip: boolean][] = [
  [0, 2, false],
  [50, 6, false],
  [8, 2, false],
  [8, 2, true],
];

for (const [available, requested, vip] of bookings) {
  const result = book(available, requested, vip);
  if (result.ok) {
    console.log(`booked, ${result.value} seats left`);
  } else {
    console.log(`not booked: ${describeError(result.error)}`);
  }
}

steps.body:
At the edge of an app, in an HTTP handler or a command's main function, each error becomes something a person or a program reads: a status code and a message. A `switch` over the error union does it, and the checker makes sure every failure gets a response:

```typescript
type LoginError = { type: "unknown_user" } | { type: "wrong_password"; attemptsLeft: number };

function toStatus(e: LoginError): 401 | 404 {
  switch (e.type) {
    case "unknown_user":
      return 404;
    case "wrong_password":
      return 401;
  }
}

console.log(toStatus({ type: "wrong_password", attemptsLeft: 2 })); // 401
```

Results are for expected failures: bad input, a missing record, a sold-out item. A bug or a broken invariant, like negative stock read back from your own database, isn't something a caller can handle, so throw an `Error` and let the app's top-level handler log it and answer with a 500. The rule of thumb: return what the caller should handle, throw what a developer must fix.

Code you don't control still throws, like `JSON.parse`. Wrap it once, at the boundary, with a `tryCatch` helper that turns a throw into a Result, so the code around it works with values only.

examples.code:
type PlaceOrderError =
  | { type: "not_found"; sku: string }
  | { type: "out_of_stock"; sku: string; available: number }
  | { type: "invalid_quantity"; quantity: number };

type ErrorResponse = { status: 404 | 409 | 422; body: { error: string } };

function toHttp(e: PlaceOrderError): ErrorResponse {
  switch (e.type) {
    case "not_found":
      return { status: 404, body: { error: `no product ${e.sku}` } };
    case "out_of_stock":
      return { status: 409, body: { error: `only ${e.available} of ${e.sku} left` } };
    case "invalid_quantity":
      return { status: 422, body: { error: `quantity must be at least 1, got ${e.quantity}` } };
    default: {
      const unhandled: never = e;
      return unhandled;
    }
  }
}

const errors: PlaceOrderError[] = [
  { type: "not_found", sku: "LAMP-09" },
  { type: "out_of_stock", sku: "MUG-01", available: 2 },
  { type: "invalid_quantity", quantity: 0 },
];

for (const e of errors) {
  const response = toHttp(e);
  console.log(`${response.status} ${JSON.stringify(response.body)}`);
}

