type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

function ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

function err<E>(error: E): Result<never, E> {
  return { ok: false, error };
}

type ReserveError =
  | { type: "invalid_quantity"; quantity: number }
  | { type: "out_of_stock"; available: number };

const stockTable = new Map<string, number>([
  ["MUG-01", 5],
  ["TEA-02", -3],
]);

function reserve(sku: string, quantity: number): Result<number, ReserveError> {
  if (!Number.isInteger(quantity) || quantity < 1) {
    return err({ type: "invalid_quantity", quantity });
  }
  const available = stockTable.get(sku) ?? 0;
  if (available < 0) {
    throw new Error(`stock for ${sku} is ${available}, which should be impossible`);
  }
  if (quantity > available) {
    return err({ type: "out_of_stock", available });
  }
  return ok(available - quantity);
}

const requests: [sku: string, quantity: number][] = [
  ["MUG-01", 2],
  ["MUG-01", 0],
  ["MUG-01", 9],
  ["TEA-02", 1],
];

for (const [sku, quantity] of requests) {
  try {
    const result = reserve(sku, quantity);
    console.log(`${sku} x ${quantity}: ${result.ok ? `${result.value} left` : result.error.type}`);
  } catch (e) {
    console.log(`${sku} x ${quantity}: 500, ${e instanceof Error ? e.message : String(e)}`);
  }
}

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

function tryCatch<T>(fn: () => T): Result<T, Error> {
  try {
    return { ok: true, value: fn() };
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e : new Error(String(e)) };
  }
}

for (const text of ['{"theme": "dark"}', "{theme: dark}"]) {
  const parsed = tryCatch((): unknown => JSON.parse(text));
  //    ^? const parsed: Result<unknown, Error>
  if (parsed.ok) {
    console.log(`parsed: ${JSON.stringify(parsed.value)}`);
  } else {
    console.log(`${parsed.error.name}: ${parsed.error.message}`);
  }
}

