export type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

export type Order = { id: string; sku: string; quantity: number };

export type PlaceOrderError =
  | { type: "not_found"; sku: string }
  | { type: "out_of_stock"; sku: string; available: number }
  | { type: "invalid_quantity"; quantity: number };

export function respond(result: Result<Order, PlaceOrderError>): { status: number; body: string } {
  if (result.ok) {
    return { status: 201, body: `created ${result.value.id}` };
  }
  const e = result.error;
  switch (e.type) {
    case "not_found":
      return { status: 404, body: `no product ${e.sku}` };
    case "out_of_stock":
      return { status: 409, body: `only ${e.available} of ${e.sku} left` };
    case "invalid_quantity":
      return { status: 422, body: `invalid quantity ${e.quantity}` };
    default: {
      const unhandled: never = e;
      return unhandled;
    }
  }
}

const outcomes: Result<Order, PlaceOrderError>[] = [
  { ok: true, value: { id: "ord-1001", sku: "MUG-01", quantity: 2 } },
  { ok: false, error: { type: "not_found", sku: "LAMP-09" } },
  { ok: false, error: { type: "out_of_stock", sku: "MUG-01", available: 1 } },
  { ok: false, error: { type: "invalid_quantity", quantity: -1 } },
];

for (const outcome of outcomes) {
  const response = respond(outcome);
  console.log(`${response.status} ${response.body}`);
}
